<?php $codigo=(string)($pedido['codigo']??'#'.($pedido['id']??0)); ?>
<style>
.delivery-page{max-width:820px;margin:0 auto}.delivery-card{padding:28px;border:1px solid var(--border);border-radius:24px;background:var(--surface);box-shadow:0 20px 55px rgba(15,23,42,.09)}.delivery-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding-bottom:20px;border-bottom:1px solid var(--border)}.delivery-head h2{margin:0 0 5px}.delivery-head p{margin:0;color:var(--text-muted)}.delivery-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:11px;margin:20px 0}.delivery-summary div{padding:13px;border:1px solid var(--border);border-radius:13px;background:var(--surface-muted)}.delivery-summary span,.delivery-summary strong{display:block}.delivery-summary span{margin-bottom:4px;color:var(--text-muted);font-size:.76rem}.delivery-form{display:grid;gap:18px}.delivery-form label{display:grid;gap:8px;font-weight:800}.delivery-form input[type=text]{width:100%;min-height:52px;padding:0 14px;border:1px solid var(--border);border-radius:13px;font:inherit}.delivery-signature{position:relative;height:250px;overflow:hidden;border:1px dashed color-mix(in srgb,var(--primary) 55%,var(--border));border-radius:16px;background:#fff}.delivery-signature.has-ink{border-color:var(--primary)}.delivery-signature canvas{position:absolute;z-index:2;inset:0;width:100%;height:100%;touch-action:none;cursor:crosshair}.delivery-signature i{position:absolute;z-index:1;left:8%;right:8%;bottom:27%;height:1px;background:#94a3b8}.delivery-signature button{position:absolute;z-index:3;right:10px;top:10px}.delivery-actions{display:flex;justify-content:flex-end;gap:10px;padding-top:4px}.delivery-actions .button{min-height:48px}@media(max-width:650px){.delivery-card{padding:18px}.delivery-head{flex-direction:column}.delivery-summary{grid-template-columns:1fr}.delivery-signature{height:210px}.delivery-actions{display:grid;grid-template-columns:1fr 1fr}}
</style>
<div class="delivery-page"><section class="delivery-card"><header class="delivery-head"><div><h2>Confirmar entrega</h2><p>Informe o recebedor e assine para concluir o pedido.</p></div><a class="button button-outline" href="<?= $esc($url('expedicao?tab=recebimento')); ?>">Voltar</a></header><div class="delivery-summary"><div><span>Pedido</span><strong><?= $esc($codigo); ?></strong></div><div><span>Romaneio</span><strong><?= $esc($expedicao['romaneio']??'—'); ?></strong></div><div><span>Volumes</span><strong><?= (int)($expedicao['volumes']??1); ?></strong></div></div><form method="post" action="<?= $esc($url('expedicao/recebimento/'.(int)$expedicao['id'])); ?>" class="delivery-form" data-delivery-page-form><label>Nome do recebedor<input type="text" name="recebedor_nome" maxlength="120" autocomplete="name" required autofocus></label><label>Assinatura do recebedor<span class="delivery-signature"><canvas data-delivery-page-canvas></canvas><i></i><button type="button" class="button button-outline" data-delivery-page-clear>Limpar</button></span><input type="hidden" name="assinatura_recebedor"></label><div class="delivery-actions"><a class="button button-outline" href="<?= $esc($url('expedicao?tab=recebimento')); ?>">Cancelar</a><button type="submit" class="button button-primary" disabled>Confirmar entrega</button></div></form></section></div>
<script>
(()=>{const form=document.querySelector('[data-delivery-page-form]'),canvas=form?.querySelector('[data-delivery-page-canvas]'),box=canvas?.closest('.delivery-signature'),hidden=form?.elements.assinatura_recebedor,name=form?.elements.recebedor_nome,submit=form?.querySelector('[type=submit]');if(!form||!canvas||!box||!hidden||!name||!submit)return;const ctx=canvas.getContext('2d');let drawing=false,ink=false;const resize=()=>{const old=hidden.value,rect=canvas.getBoundingClientRect(),ratio=devicePixelRatio||1;if(rect.width<2||rect.height<2)return;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.strokeStyle='#111827';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round';if(old){const image=new Image();image.onload=()=>{ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.drawImage(image,0,0,canvas.width,canvas.height);ctx.restore();ctx.setTransform(ratio,0,0,ratio,0,0)};image.src=old}};const update=()=>{submit.disabled=!(name.value.trim()&&hidden.value)};const save=()=>{if(ink)hidden.value=canvas.toDataURL('image/png');update()};const clear=()=>{ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.restore();hidden.value='';drawing=false;ink=false;box.classList.remove('has-ink');update()};const point=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};resize();name.addEventListener('input',update);canvas.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;ink=true;box.classList.add('has-ink');const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+.1,p.y+.1);ctx.stroke();try{canvas.setPointerCapture(e.pointerId)}catch(error){}});canvas.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke();save()});const finish=e=>{if(!drawing)return;drawing=false;save();try{canvas.releasePointerCapture(e.pointerId)}catch(error){}};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);window.addEventListener('pointerup',finish,true);form.querySelector('[data-delivery-page-clear]').addEventListener('click',clear);window.addEventListener('resize',()=>{if(!drawing)resize()});form.addEventListener('submit',e=>{save();if(!name.value.trim()||!hidden.value){e.preventDefault();window.showAppToast?.('Informe o recebedor e faça a assinatura.','error')}});update()})();
</script>
